public inherited sharing class Opportunities extends fflib_SObjectDomain {
    public static final String NEGATIVE_AMOUNT_ERROR = 'Amount cannot be negative.';
    public static final String WON_AMOUNT_CHANGE_ERROR = 'Amount cannot change on a won opportunity.';
    public static final String CLOSED_WON_STAGE = 'Closed Won';

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    public override void onValidate() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                opp.addError(
                    Opportunity.Amount,
                    error(NEGATIVE_AMOUNT_ERROR, opp, Opportunity.Amount)
                );
            }
        }
    }

    public override void onValidate(Map<Id, SObject> existingRecords) {
        onValidate();
        for (Opportunity opp : (List<Opportunity>) Records) {
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (
                oldOpp != null &&
                oldOpp.StageName == CLOSED_WON_STAGE &&
                opp.Amount != oldOpp.Amount
            ) {
                opp.addError(
                    Opportunity.Amount,
                    error(WON_AMOUNT_CHANGE_ERROR, opp, Opportunity.Amount)
                );
            }
        }
    }
}
