public with sharing class EmployeeDirectoryService {
    @AuraEnabled(cacheable=true)
    public static List<FB_Employee__c> getDirectory() {
        if (!Schema.sObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        List<String> fields = new List<String>{ 'Id', 'Name' };
        Map<String, Schema.SObjectField> fieldMap = Schema.sObjectType.FB_Employee__c.fields.getMap();

        for (String fieldName : new List<String>{ 'Department__c', 'Salary__c', 'Personal_Email__c' }) {
            Schema.SObjectField fieldToken = fieldMap.get(fieldName);
            if (fieldToken != null && fieldToken.getDescribe().isAccessible()) {
                fields.add(fieldName);
            }
        }

        String soql =
            'SELECT ' +
            String.join(fields, ', ') +
            ' FROM FB_Employee__c ORDER BY Name ASC';

        List<FB_Employee__c> employees = Database.query(soql);

        SObjectAccessDecision decision = Security.stripInaccessible(
            AccessType.READABLE,
            employees
        );

        return (List<FB_Employee__c>) decision.getRecords();
    }
}
